function dateKey(value){if(!value)return '';const date=new Date(value);if(Number.isNaN(date.getTime()))return String(value).slice(0,10);const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Karachi',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(date);const part=Object.fromEntries(parts.map(x=>[x.type,x.value]));return `${part.year}-${part.month}-${part.day}`;}
