  async function refreshMovements(){if(!connected)return;const{data,error}=await supabase.from('inventory_movements').select('*').order('movement_date',{ascending:false}).limit(500);if(!error)setMovements(data.map(x=>({id:x.id,item_name:x.item_name,unit:x.unit,type:x.movement_type,quantity_change:Number(x.quantity_change),quantity_after:Number(x.quantity_after),date:x.movement_date,note:x.note})));}
  async function saveCateringQuote(data){const items=data.items.filter(x=>x.recipe_id&&Number(x.batch_qty)>0).map(x=>({recipe_id:x.recipe_id,batch_qty:Number(x.batch_qty),profit_percent:Number(data.profit_percent)||0}));if(!data.customer_name.trim()||!items.length)return showToast('Add a customer name and at least one catering item.');const{data:quoteId,error}=await supabase.rpc('create_catering_quote',{p_customer_name:data.customer_name,p_customer_phone:data.customer_phone,p_event_name:data.event_name,p_event_date:data.event_date||null,p_venue:data.venue,p_notes:data.notes,p_items:items,p_discount_type:data.discount_type||'none',p_discount_value:Number(data.discount_value)||0});if(error)return showToast(error.message);const{data:row,error:readError}=await supabase.from('catering_quotes').select('*, catering_quote_items(*)').eq('id',quoteId).single();if(readError)return showToast(`Quote saved, but could not load it: ${readError.message}`);const quote=mapCateringQuote(row);setCateringQuotes(a=>[quote,...a]);showToast('Catering quotation saved');return quote;}
