function BranchAccountRemoveModal({account,historyCount,onClose,onConfirm}){const canRemove=Number(account.current_balance||0)===0,action=historyCount?'Archive':'Delete';return <Modal title={`${action} account?`} subtitle={account.name} onClose={onClose}><p>{!canRemove?`This account has a balance of ${money(account.current_balance)}. Transfer or subtract it before removing the account.`:historyCount?'Past account history will be kept.':'This empty account has no transaction history.'}</p><div className="modal-actions"><button className="btn btn-soft" onClick={onClose}>Cancel</button><button className="btn btn-primary" disabled={!canRemove} onClick={onConfirm}>{canRemove?`${action} account`:'Balance must be zero'}</button></div></Modal>}
function BranchCheckoutPanel({order,onClose,onCloseBill}){const subtotal=Number(order.subtotal||0),[discountType,setDiscountType]=useState('none'),[discountValue,setDiscountValue]=useState('0'),[selectedMethod,setSelectedMethod]=useState('cash'),[payments,setPayments]=useState({cash:String(subtotal),card:'0',online:'0'}),discount=discountType==='percent'?Math.min(subtotal,subtotal*Math.max(0,Number(discountValue)||0)/100):discountType==='fixed'?Math.min(subtotal,Math.max(0,Number(discountValue)||0)):0,total=Math.max(0,subtotal-discount),paid=Object.values(payments).reduce((sum,v)=>sum+(Number(v)||0),0),setPayment=(k,v)=>setPayments(p=>({...p,[k]:v})),selectMethod=method=>{setSelectedMethod(method);setPayments({cash:method==='cash'?String(total):'0',card:method==='card'?String(total):'0',online:method==='online'?String(total):'0'})};useEffect(()=>{setPayments(current=>{const active=Object.entries(current).filter(([,amount])=>Number(amount)>0);return active.length===1&&active[0][0]===selectedMethod?{...current,[selectedMethod]:String(total)}:current})},[total,selectedMethod]);return <section className="panel pos-checkout-screen"><div className="pos-inline-heading"><div><span>PAYMENT</span><h2>Close bill {order.order_number}</h2><p>{(order.items||[]).map(i=>`${i.item_name} x ${i.quantity}`).join(' | ')}</p></div><button className="btn btn-soft" onClick={onClose}>Back to POS</button></div><div className="pos-checkout-columns"><section className="pos-discount-panel"><h3>Discount</h3><label className="field"><span>Discount type</span><select className="input" value={discountType} onChange={e=>setDiscountType(e.target.value)}><option value="none">No discount</option><option value="percent">Percentage</option><option value="fixed">Fixed amount</option></select></label>{discountType!=='none'&&<label className="field"><span>{discountType==='percent'?'Discount percent':'Discount amount (Rs)'}</span><input className="input" type="number" min="0" step="0.01" value={discountValue} onChange={e=>setDiscountValue(e.target.value)}/></label>}<div className="pos-total-row"><span>Subtotal</span><b>{money(subtotal)}</b></div><div className="pos-total-row"><span>Discount</span><b>- {money(discount)}</b></div><div className="pos-total-row"><span>Final bill</span><b>{money(total)}</b></div></section><section className="pos-payment-panel"><div className="pos-modal-section-title">Choose payment method</div><div className="pos-payment-choice"><div className="pos-service-switch">{[['cash','Cash'],['card','Card'],['online','Online']].map(([method,label])=><button type="button" key={method} className={selectedMethod===method?'active':''} onClick={()=>selectMethod(method)}>{label}</button>)}</div><small>Choose a method to fill the bill total, or edit the amounts below to split payment.</small></div><h3>Payment amounts</h3>{[['cash','Cash'],['card','Card'],['online','Online']].map(([key,label])=><label className="field" key={key}><span>{label} (Rs)</span><input className="input" type="number" min="0" step="0.01" value={payments[key]} onChange={e=>setPayment(key,e.target.value)}/></label>)}<div className="pos-total-row"><span>Paid</span><b>{money(paid)}</b></div><div className="pos-total-row"><span>Remaining</span><b>{money(Math.max(0,total-paid))}</b></div></section></div><div className="pos-inline-actions"><button className="btn btn-soft" onClick={onClose}>Cancel</button><button className="btn btn-primary" disabled={Math.abs(paid-total)>0.01} onClick={()=>onCloseBill({order,discount_type:discountType,discount_value:Number(discountValue)||0,payments:Object.entries(payments).map(([method,amount])=>({method,amount:Number(amount)||0}))})}><Check size={16}/>Close bill and print</button></div></section>}
