 const orderDate=o=>dateKey(o.closed_at||o.created_at),todayOrders=orders.filter(o=>o.status==='closed'&&orderDate(o)===today()),todayExpenses=expenses.filter(e=>e.expense_date===today()),sales=todayOrders.reduce((sum,o)=>sum+Number(o.total_amount||0),0),expenseTotal=todayExpenses.reduce((sum,e)=>sum+Number(e.amount||0),0),paymentTotals={cash:0,card:0,online:0};
